// @amorph-auto-ui-generated
// WINDOW SIZE: 600x200
const VARIANT = 'fx';
const PRESET_TITLE = 'stereowidener';
const USE_SECTIONS = false;
const sectionLayout = [];

// ââ DialControl ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
class DialControl
{
    constructor (options)
    {
        this.patchConnection = options.patchConnection;
        this.param = options.param;
        this.knob = options.knob;
        this.valueLabel = options.valueLabel;
        this.formatValue = options.formatValue;
        this.onChange = options.onChange;
        this.min = options.min;
        this.max = options.max;
        this.step = options.step;
        this.defaultValue = options.defaultValue;

        if (! (this.max > this.min)) { this.min = 0; this.max = 1; }
        // step 0 = continuous (cmaj contract). Never synthesise a grid here: a
        // range/100 fallback quantised the annotated init on load and capped
        // drag resolution at 100 positions (T-369 F-1).
        if (! (this.step > 0)) this.step = 0;

        this.value = this.defaultValue;
        this.dragging = false;
        this.startValue = this.value;
        this.startY = 0;
        this.activePointerId = null;

        this.knob.addEventListener("pointerdown", (e) => this.onPointerDown(e));
        this.knob.addEventListener("pointermove", (e) => this.onPointerMove(e));
        this.knob.addEventListener("pointerup", (e) => this.onPointerUp(e));
        this.knob.addEventListener("pointercancel", (e) => this.onPointerUp(e));
        this.knob.addEventListener("lostpointercapture", () => this.cancelDrag());
        this.knob.addEventListener("dragstart", (e) => e.preventDefault());
        this.knob.addEventListener("dblclick", () => this.setValue(this.defaultValue, true, false));
        this.setValue(this.defaultValue, false, false);
    }

    // Quantisation is a pointer-input affordance only. The init and any value
    // the DSP reports back are shown and recalled exactly as declared.
    setValue (value, notify, snapToStep = notify === true)
    {
        const n = Number.isFinite(value) ? value : this.defaultValue;
        this.value = this.clamp(snapToStep ? this.quantize(n) : n, this.min, this.max);
        this.updateVisuals();
        if (this.valueLabel) this.valueLabel.textContent = this.formatValue(this.value);
        if (this.onChange) this.onChange(this.value);
        if (notify === true) this.patchConnection.sendEventOrValue(this.param, this.value);
    }

    updateVisuals()
    {
        const norm = this.max > this.min ? (this.value - this.min) / (this.max - this.min) : 0;
        const cn = this.clamp(norm, 0, 1);
        this.knob.style.setProperty("--norm", `${cn}`);
    }

    setDraggingState (d)
    {
        this.dragging = d;
        this.knob.classList.toggle("is-dragging", d);
        const root = this.knob.closest(".auto-ui-root");
        if (root) root.classList.toggle("is-dragging", d);
    }
    cancelDrag () { this.setDraggingState(false); this.activePointerId = null; }

    onPointerDown (e)
    {
        if ((e.button !== undefined && e.button !== 0) || e.isPrimary === false) return;
        e.preventDefault(); e.stopPropagation();
        this.startY = e.clientY; this.startValue = this.value;
        this.activePointerId = e.pointerId; this.setDraggingState(true);
        try { this.knob.setPointerCapture(e.pointerId); } catch (_) {}
    }

    onPointerMove (e)
    {
        if (!this.dragging || this.activePointerId !== e.pointerId) return;
        e.preventDefault();
        const delta = this.startY - e.clientY;
        const sens = (this.max - this.min) / 170;
        this.setValue(this.startValue + delta * sens * (e.shiftKey ? 0.2 : 1.0), true);
    }

    onPointerUp (e)
    {
        if (!this.dragging || this.activePointerId !== e.pointerId) return;
        e.preventDefault(); e.stopPropagation();
        this.setDraggingState(false); this.activePointerId = null;
        try { if (this.knob.hasPointerCapture(e.pointerId)) this.knob.releasePointerCapture(e.pointerId); } catch (_) {}
    }

    clamp (v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
    quantize (v) { return this.step > 0 ? this.min + Math.round((v - this.min) / this.step) * this.step : v; }
}

// ââ ToggleControl ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
class ToggleControl
{
    constructor (options)
    {
        this.patchConnection = options.patchConnection;
        this.param = options.param;
        this.el = options.el;
        this.valueLabel = options.valueLabel;
        this.formatValue = options.formatValue;
        this.onChange = options.onChange;
        this.min = options.min;
        this.max = options.max;
        this.defaultValue = options.defaultValue;
        this.value = this.defaultValue;

        this.el.addEventListener("click", () => {
            const next = this.value <= this.min ? this.max : this.min;
            this.setValue(next, true);
        });
        this.el.addEventListener("dblclick", () => this.setValue(this.defaultValue, true));
        this.setValue(this.defaultValue, false);
    }

    setValue (value, notify)
    {
        const n = Number.isFinite(value) ? value : this.defaultValue;
        this.value = n > (this.min + this.max) / 2 ? this.max : this.min;
        this.el.classList.toggle("toggle-on", this.value > this.min);
        if (this.valueLabel) this.valueLabel.textContent = this.formatValue(this.value);
        if (this.onChange) this.onChange(this.value);
        if (notify === true) this.patchConnection.sendEventOrValue(this.param, this.value);
    }
    cancelDrag () {}
}

// ââ SegmentedControl âââââââââââââââââââââââââââââââââââââââââââââââââââââââ
class SegmentedControl
{
    constructor (options)
    {
        this.patchConnection = options.patchConnection;
        this.param = options.param;
        this.el = options.el;
        this.valueLabel = options.valueLabel;
        this.formatValue = options.formatValue;
        this.onChange = options.onChange;
        this.min = options.min;
        this.max = options.max;
        this.step = options.step > 0 ? options.step : 1;
        this.defaultValue = options.defaultValue;
        this.labels = options.labels || [];
        this.value = this.defaultValue;

        this.buttons = this.el.querySelectorAll(".seg-btn");
        this.buttons.forEach((btn, idx) => {
            btn.addEventListener("click", () => {
                this.setValue(this.min + idx * this.step, true);
            });
        });
        this.el.addEventListener("dblclick", () => this.setValue(this.defaultValue, true));
        this.setValue(this.defaultValue, false);
    }

    setValue (value, notify)
    {
        const n = Number.isFinite(value) ? value : this.defaultValue;
        const clamped = Math.max(this.min, Math.min(this.max, n));
        const idx = Math.round((clamped - this.min) / this.step);
        this.value = this.min + idx * this.step;
        this.buttons.forEach((btn, i) => btn.classList.toggle("seg-active", i === idx));
        if (this.valueLabel) this.valueLabel.textContent = this.formatValue(this.value);
        if (this.onChange) this.onChange(this.value);
        if (notify === true) this.patchConnection.sendEventOrValue(this.param, this.value);
    }
    cancelDrag () {}
}

