    {
        const norm = this.max > this.min ? (this.value - this.min) / (this.max - this.min) : 0;
        const cn = this.clamp(norm, 0, 1);
        if (this.fill) this.fill.style.width = `${cn * 100}%`;
        if (this.thumb) this.thumb.style.left = `${cn * 100}%`;
    }

    setDraggingState (d)
    {
        this.dragging = d;
        this.track.classList.toggle("is-dragging", d);
        const root = this.track.closest(".auto-ui-root");
        if (root) root.classList.toggle("is-dragging-slider", d);
    }
    cancelDrag () { this.setDraggingState(false); this.activePointerId = null; }

    valueFromClientX (clientX)
    {
        const rect = this.track.getBoundingClientRect();
        if (! (rect.width > 0)) return this.value;
        const norm = this.clamp((clientX - rect.left) / rect.width, 0, 1);
        return this.min + norm * (this.max - this.min);
    }

    onPointerDown (e)
    {
        if ((e.button !== undefined && e.button !== 0) || e.isPrimary === false) return;
        e.preventDefault(); e.stopPropagation();
        this.activePointerId = e.pointerId; this.setDraggingState(true);
        try { this.track.setPointerCapture(e.pointerId); } catch (_) {}
        this.setValue(this.valueFromClientX(e.clientX), true);
    }

    onPointerMove (e)
    {
        if (!this.dragging || this.activePointerId !== e.pointerId) return;
        e.preventDefault();
        this.setValue(this.valueFromClientX(e.clientX), true);
    }

    onPointerUp (e)
    {
        if (!this.dragging || this.activePointerId !== e.pointerId) return;
        e.preventDefault(); e.stopPropagation();
        this.setDraggingState(false); this.activePointerId = null;
        try { if (this.track.hasPointerCapture(e.pointerId)) this.track.releasePointerCapture(e.pointerId); } catch (_) {}
    }

    clamp (v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
    quantize (v) { return this.step > 0 ? this.min + Math.round((v - this.min) / this.step) * this.step : v; }
}

// ââ AutoPatchView ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
class AutoPatchView extends HTMLElement
{
    constructor (patchConnection)
    {
        super();
        this.patchConnection = patchConnection;
        this.className = "auto-ui-root";
        this.paramSpecs = [
            { id: 'param1', label: 'Param 1', min: 0, max: 1, step: 0, init: 0.5, unit: '', labels: [], controlType: 'dial' },
            { id: 'param2', label: 'Param 2', min: 0, max: 1, step: 0, init: 0.5, unit: '', labels: [], controlType: 'dial' },
            { id: 'param3', label: 'Param 3', min: 0, max: 1, step: 0, init: 0.5, unit: '', labels: [], controlType: 'dial' },
            { id: 'param4', label: 'Param 4', min: 0, max: 1, step: 0, init: 0.5, unit: '', labels: [], controlType: 'dial' }
        ];
        this.innerHTML = this.getHTML();
        this.controls = new Map();
        this._animFrame = null;
        this._midiViz = null;
    }

    connectedCallback()
    {
        this.querySelectorAll(".control").forEach((node) =>
        {
            const param = node.dataset.param;
            const spec = this.paramSpecs.find((s) => s.id === param);
            if (!spec) return;

            const type = spec.controlType || "dial";
            let ctrl;

            if (type === "toggle")
            {
                ctrl = new ToggleControl({
                    patchConnection: this.patchConnection, param,
                    el: node.querySelector(".toggle-btn"),
                    valueLabel: node.querySelector(".control-value"),
                    formatValue: (v) => this.formatValue(spec, v),
                    onChange: () => {}, min: spec.min, max: spec.max,
                    defaultValue: spec.init
                });
            }
            else if (type === "segmented")

            {
                ctrl = new SegmentedControl({
                    patchConnection: this.patchConnection, param,
                    el: node.querySelector(".seg-group"),
                    valueLabel: node.querySelector(".control-value"),
                    formatValue: (v) => this.formatValue(spec, v),
                    onChange: () => {}, min: spec.min, max: spec.max,
                    step: spec.step, defaultValue: spec.init,
                    labels: spec.labels
                });
            }
            else if (type === "stepper")
            {
                ctrl = new StepperControl({
                    patchConnection: this.patchConnection, param,
                    el: node,
                    valueLabel: node.querySelector(".control-value"),
                    formatValue: (v) => this.formatValue(spec, v),
                    onChange: () => {}, min: spec.min, max: spec.max,
                    step: spec.step, defaultValue: spec.init
                });
            }
            else if (type === "slider")
            {
                const track = node.querySelector(".slider-track");
                if (!track) return;
                ctrl = new SliderControl({
                    patchConnection: this.patchConnection, param,
                    track,
                    fill: node.querySelector(".slider-fill"),
                    thumb: node.querySelector(".slider-thumb"),
                    valueLabel: node.querySelector(".control-value"),
                    formatValue: (v) => this.formatValue(spec, v),
                    onChange: () => {},
                    min: spec.min, max: spec.max, step: spec.step,
                    defaultValue: spec.init
                });
            }
            else
            {
                const knob = node.querySelector(".knob");
                const valueLabel = node.querySelector(".control-value");
                if (!knob || !valueLabel) return;
                ctrl = new DialControl({
                    patchConnection: this.patchConnection, param, knob, valueLabel,
                    min: spec.min, max: spec.max, step: spec.step,
                    defaultValue: spec.init,
                    formatValue: (v) => this.formatValue(spec, v),
                    onChange: () => {}
                });
            }

            this.controls.set(param, ctrl);
            this.patchConnection.requestParameterValue(param);
        });

        this.paramListener = (event) =>
        {
            const control = this.controls.get(event.endpointID);
            if (control) control.setValue(Number(event.value), false);
        };
        this.patchConnection.addAllParameterListener(this.paramListener);

        // FX / Instrument: start RMS meter animation (Inst = OUT strip only)
        if (VARIANT === 'fx' || VARIANT === 'instrument') this._startMeterLoop();

        // MIDI/Instrument: wire keyboard
        if (VARIANT === 'midi' || VARIANT === 'instrument') this._initKeyboard();

        this._startAnimLoop();
    }

    disconnectedCallback()
    {
        this.controls.forEach((c) => c.cancelDrag());
        if (this.paramListener)
            this.patchConnection.removeAllParameterListener(this.paramListener);
        if (this._animFrame) { cancelAnimationFrame(this._animFrame); this._animFrame = null; }
        if (this._prevMidiHandler !== undefined)
        {
            if (this._prevMidiHandler) window.__amorphProcessMidi = this._prevMidiHandler;
            else delete window.__amorphProcessMidi;
        }
        if (this._prevMidiOutHandler !== undefined)
        {
            if (this._prevMidiOutHandler) window.__amorphProcessMidiOut = this._prevMidiOutHandler;
            else delete window.__amorphProcessMidiOut;
        }
    }

    // ââ RMS Meter (FX rack + Instrument OUT strip) âââââââââââââââââââââ
    _startMeterLoop ()
    {
        this._meterHorizontal = !!this.querySelector(".meter-out-strip");
        this._meterInL = this.querySelector(".meter-bar.in-l .meter-fill");
        this._meterInR = this.querySelector(".meter-bar.in-r .meter-fill");
        this._meterOutL = this.querySelector(".meter-bar.out-l .meter-fill")
            || this.querySelector(".meter-out-strip .meter-fill.out-l");
        this._meterOutR = this.querySelector(".meter-bar.out-r .meter-fill")
            || this.querySelector(".meter-out-strip .meter-fill.out-r");
    }

    _updateMeters ()
    {
        if (!window.__amorphRmsLevels) return;
        const { inL, inR, outL, outR } = window.__amorphRmsLevels;
        const toDB = (v) => v > 0.00001 ? 20 * Math.log10(v) : -100;
        const dbToNorm = (db) => Math.max(0, Math.min(1, (db + 60) / 60));
        const horizontal = !!this._meterHorizontal;

        const setBar = (el, db) => {
            if (!el) return;
            const n = dbToNorm(db);
            if (horizontal) el.style.width = `${n * 100}%`;
            else el.style.height = `${n * 100}%`;
            if (db > -3) el.classList.add("clip");
            else if (db > -12) { el.classList.remove("clip"); el.classList.add("hot"); }
            else { el.classList.remove("clip"); el.classList.remove("hot"); }
        };
        if (! horizontal)
        {
            setBar(this._meterInL, toDB(inL));
            setBar(this._meterInR, toDB(inR));
        }
        setBar(this._meterOutL, toDB(outL));
        setBar(this._meterOutR, toDB(outR));
    }


    // ââ Keyboard (MIDI/Instrument) âââââââââââââââââââââââââââââââââââââ
    _initKeyboard ()
    {
        this._activeNotes = new Set();
        this._optimisticNotes = new Set();
        this._outputNotes = new Set();
        const container = this.querySelector(".keyboard-strip");
        if (!container) return;

        this._prevMidiHandler = window.__amorphProcessMidi ?? null;
        window.__amorphProcessMidi = (messages) => {
            this._prevMidiHandler?.(messages);
            messages.forEach(msg => {
                const type = msg.s & 0xF0;
                if (type === 0x90 && msg.d2 > 0) this._activeNotes.add(msg.d1);
                else if (type === 0x80 || (type === 0x90 && msg.d2 === 0)) this._activeNotes.delete(msg.d1);
            });
        };

        if (VARIANT === 'midi')
        {
            this._prevMidiOutHandler = window.__amorphProcessMidiOut ?? null;
            window.__amorphProcessMidiOut = (messages) => {
                this._prevMidiOutHandler?.(messages);
                messages.forEach(msg => {
                    const type = msg.s & 0xF0;
                    if (type === 0x90 && msg.d2 > 0) this._outputNotes.add(msg.d1);
                    else if (type === 0x80 || (type === 0x90 && msg.d2 === 0)) this._outputNotes.delete(msg.d1);
                });
            };
        }

        // Instrument: clickable keys + optimistic press highlight (N51)
        if (VARIANT === 'instrument')
        {
            container.querySelectorAll("[data-note]").forEach(key => {
                key.style.cursor = "pointer";
                key.addEventListener("pointerdown", (e) => {
                    e.preventDefault();
                    const note = parseInt(key.dataset.note, 10);
                    this._optimisticNotes.add(note);
                    this.patchConnection.sendMIDIInputEvent("midiIn", (0x90 << 16) | (note << 8) | 100);
                    key.setPointerCapture(e.pointerId);
                });
                const release = (e) => {
                    const note = parseInt(key.dataset.note, 10);
                    this._optimisticNotes.delete(note);
                    this.patchConnection.sendMIDIInputEvent("midiIn", (0x80 << 16) | (note << 8) | 0);
                };
                key.addEventListener("pointerup", release);
                key.addEventListener("pointercancel", release);
            });
        }
    }

    _updateKeyboard ()
    {
        const strip = this.querySelector(".keyboard-strip");
        if (!strip) return;
        strip.querySelectorAll("[data-note]").forEach(key => {
            const note = parseInt(key.dataset.note, 10);
            const isInput = this._activeNotes?.has(note) || this._optimisticNotes?.has(note);
            const isOutput = this._outputNotes?.has(note);
            key.classList.toggle("key-input", !!isInput && !isOutput);
            key.classList.toggle("key-output", !!isOutput && !isInput);
            key.classList.toggle("key-both", !!isInput && !!isOutput);
        });
    }

    // ââ Animation loop âââââââââââââââââââââââââââââââââââââââââââââââââ
    _startAnimLoop ()
    {
        const tick = () => {
            if (VARIANT === 'fx' || VARIANT === 'instrument') this._updateMeters();
            if (VARIANT === 'midi' || VARIANT === 'instrument') this._updateKeyboard();
            this._animFrame = requestAnimationFrame(tick);
        };
        this._animFrame = requestAnimationFrame(tick);
    }

    // ââ Formatting âââââââââââââââââââââââââââââââââââââââââââââââââââââ
    getDecimals (step)
    {
        if (!Number.isFinite(step) || step <= 0) return 2;
        const t = String(step), d = t.indexOf(".");
        return d < 0 ? 0 : Math.min(6, t.length - d - 1);
    }

    formatValue (spec, value)
    {
        const v = Number.isFinite(value) ? value : Number(spec.init) || 0;
        const min = Number.isFinite(spec.min) ? spec.min : 0;
        const max = Number.isFinite(spec.max) ? spec.max : 1;
        const clamped = Math.max(min, Math.min(max, v));

        if (Array.isArray(spec.labels) && spec.labels.length > 0)
        {
            const step = Number.isFinite(spec.step) && spec.step > 0 ? spec.step : 1;
            let idx = Math.round((clamped - min) / step);
            idx = Math.max(0, Math.min(spec.labels.length - 1, idx || 0));
            return String(spec.labels[idx]);
        }

        // Toggle: show On/Off
        if (spec.controlType === 'toggle')
            return clamped > (min + max) / 2 ? 'On' : 'Off';

        // Unit-aware formatting
        const unit = spec.unit || '';
        if (unit === 'Hz' && clamped >= 1000)
            return (clamped / 1000).toFixed(1) + ' kHz';
        if (unit === 'ms' && clamped >= 1000)
            return (clamped / 1000).toFixed(2) + ' s';
        if (!unit && min === 0 && max === 1 && spec.step < 1)
            return Math.round(clamped * 100) + '%';

        const dec = this.getDecimals(spec.step);
        const base = clamped.toFixed(dec);
        return unit ? `${base} ${unit}` : base;
    }

    escapeHTML (t)
    {
        return String(t).replaceAll("&","&amp;").replaceAll("<","&lt;")
            .replaceAll(">","&gt;").replaceAll("\"","&quot;").replaceAll("'","&#39;");
    }

    // ââ HTML generation ââââââââââââââââââââââââââââââââââââââââââââââââ
    _controlHTML (spec)
    {
        const type = spec.controlType || 'dial';
        const dataAttrs = `data-param="${spec.id}" data-endpoint-id="${spec.id}" data-min="${spec.min}" data-max="${spec.max}" data-step="${spec.step}" data-init="${spec.init}"`;

        if (type === 'toggle')
        {
            const on = spec.init > (spec.min + spec.max) / 2;
            return `<div class="control control-toggle" ${dataAttrs}>
                <button class="toggle-btn${on ? ' toggle-on' : ''}" type="button">
                    <span class="toggle-track"><span class="toggle-thumb"></span></span>
                </button>
                <span class="control-value">${this.formatValue(spec, spec.init)}</span>
                <span class="control-label">${this.escapeHTML(spec.label)}</span>
            </div>`;
        }

        if (type === 'segmented')
        {
            const step = spec.step > 0 ? spec.step : 1;
            const count = Math.round((spec.max - spec.min) / step) + 1;
            const initIdx = Math.round((spec.init - spec.min) / step);
            let btns = '<div class="seg-group">';
            for (let i = 0; i < count; i++)
            {
                const label = (spec.labels && spec.labels[i]) ? this.escapeHTML(spec.labels[i]) : String(spec.min + i * step);
                btns += `<button class="seg-btn${i === initIdx ? ' seg-active' : ''}" type="button">${label}</button>`;
            }
            btns += '</div>';
            return `<div class="control control-segmented" ${dataAttrs}>
                ${btns}
                <span class="control-value">${this.formatValue(spec, spec.init)}</span>
                <span class="control-label">${this.escapeHTML(spec.label)}</span>
            </div>`;
        }

        if (type === 'stepper')
        {
            return `<div class="control control-stepper" ${dataAttrs}>
                <div class="stepper-row">
                    <button class="stepper-dec" type="button">-</button>
                    <span class="control-value">${this.formatValue(spec, spec.init)}</span>
                    <button class="stepper-inc" type="button">+</button>
                </div>
                <span class="control-label">${this.escapeHTML(spec.label)}</span>
            </div>`;
        }

        if (type === 'slider')
        {
            return `<div class="control control-slider" ${dataAttrs}>
                <span class="control-label">${this.escapeHTML(spec.label)}</span>
                <div class="slider-row">
                    <div class="slider-track">
                        <div class="slider-fill"></div>
                        <div class="slider-thumb"></div>
                    </div>
                    <span class="control-value">${this.formatValue(spec, spec.init)}</span>
                </div>
            </div>`;
        }

        // Default: dial (arc fill only â no pointer)
        return `<div class="control control-dial" ${dataAttrs}>
            <div class="knob">
                <div class="knob-track"></div>
                <div class="knob-fill"></div>
                <div class="knob-core"></div>

                <span class="control-value">${this.formatValue(spec, spec.init)}</span>
            </div>
            <span class="control-label">${this.escapeHTML(spec.label)}</span>
        </div>`;
    }

    _keyboardHTML ()
    {
        const BLACK = new Set([1, 3, 6, 8, 10]);
        const whites = [];
        const blacks = [];
        let wCount = 0;
        for (let n = 48; n <= 84; n++)
        {
            if (BLACK.has(n % 12)) { blacks.push({ n, pos: wCount }); }
            else { whites.push(n); wCount++; }
        }
        let html = '<div class="keyboard-strip">';
        for (const n of whites)
            html += `<div class="key key-white" data-note="${n}"></div>`;
        const bw = 60 / wCount;
        for (const { n: note, pos } of blacks)
        {
            const left = (pos / wCount) * 100 - bw / 2;
            html += `<div class="key key-black" data-note="${note}" style="left:${left.toFixed(2)}%;width:${bw.toFixed(2)}%"></div>`;
        }
        return html + '</div>';
    }

    _meterHTML ()
    {
        return `<div class="meter-rack">
            <div class="meter-group"><span class="meter-label">IN</span>
                <div class="meter-bar in-l"><div class="meter-fill"></div></div>
                <div class="meter-bar in-r"><div class="meter-fill"></div></div>
            </div>
            <div class="meter-group"><span class="meter-label">OUT</span>
                <div class="meter-bar out-l"><div class="meter-fill"></div></div>
                <div class="meter-bar out-r"><div class="meter-fill"></div></div>
            </div>
        </div>`;
    }

    /** N52 â Instrument OUT-only strip (above keyboard). */
    _meterOutStripHTML ()
    {
        return `<div class="meter-out-strip">
            <span class="meter-out-label">OUT</span>
            <div class="meter-out-bars">
                <div class="meter-out-track"><div class="meter-fill out-l"></div></div>
                <div class="meter-out-track"><div class="meter-fill out-r"></div></div>
            </div>
        </div>`;
    }

    _variantBadge ()
    {
        const badges = { fx: 'FX', midi: 'MIDI', instrument: 'INST' };
        return badges[VARIANT] || 'FX';
    }

    _controlsBodyHTML ()
    {
        if (USE_SECTIONS && Array.isArray(sectionLayout) && sectionLayout.length > 0)
        {
            const specById = new Map(this.paramSpecs.map(s => [s.id, s]));
            const loneUntitled = sectionLayout.length === 1
                && !(sectionLayout[0].title || '').trim();
            return sectionLayout.map(section =>
            {
                const cells = (section.ids || []).map(id =>
                {
                    const spec = specById.get(id);
                    return spec ? this._controlHTML(spec) : '';
                }).join("");
                const title = (section.title || '').trim();
                // N50 â lone untitled section: no floating card (full-width grid).
                if (loneUntitled)
                    return `<div class="section-grid">${cells}</div>`;
                const titleHtml = title
                    ? `<div class="section-title">${this.escapeHTML(title)}</div>`
                    : '';
                return `<div class="section-card">
                    ${titleHtml}
                    <div class="section-grid">${cells}</div>
                </div>`;
            }).join("");
        }

        return this.paramSpecs.map(s => this._controlHTML(s)).join("");
    }

    getHTML()
    {
        const hasMeter = VARIANT === 'fx';
        const hasOutStrip = VARIANT === 'instrument';
        const hasKeyboard = VARIANT === 'midi' || VARIANT === 'instrument';
        const useSectionLayout = USE_SECTIONS && Array.isArray(sectionLayout) && sectionLayout.length > 0;
        const controlsInner = this._controlsBodyHTML();
        // N50 â only when one section: avoid half-width card in a 2-col sections grid.
        const sectionsClass = (useSectionLayout && sectionLayout.length <= 1)
            ? 'sections-grid sections-grid--single'
            : 'sections-grid';
        const controlsMarkup = useSectionLayout
            ? `<div class="controls-wrap"><div class="${sectionsClass}">${controlsInner}</div></div>`
            : `<div class="controls-grid">${controlsInner}</div>`;
        const outStripMarkup = hasOutStrip ? this._meterOutStripHTML() : '';
        const keyboardMarkup = hasKeyboard ? this._keyboardHTML() : '';

        return `
<style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html, body { overflow: hidden; margin: 0; padding: 0; }

    :host, .auto-ui-root {
        --au-fg: #F2F2F2;
        --au-muted: rgba(255,255,255,0.42);
        --au-dim: rgba(255,255,255,0.14);
        --au-active: #F2F2F2;
        --au-track: rgba(255,255,255,0.10);
        display: block; width: 100%; height: 100%; overflow: hidden;
        font-family: "Space Grotesk", system-ui, -apple-system, sans-serif;
        background: rgb(20, 20, 20);
        color: var(--au-fg);
        user-select: none; -webkit-user-select: none;
    }

    .auto-ui-shell {
        position: fixed; inset: 0;
        display: flex; flex-direction: column;
        background: rgb(20, 20, 20);
        overflow: hidden;
    }

    /* ââ Title bar ââ */
    .title-bar {
        display: flex; align-items: center; gap: 12px;
        padding: 10px 16px 8px;
        background: rgba(255, 255, 255, 0.03);
        border-bottom: none;
        flex-shrink: 0;
    }
    .title-bar .badge {
        font-family: "Space Grotesk", system-ui, sans-serif;
        font-size: 10px; font-weight: 700; letter-spacing: 0.08em;
        text-transform: uppercase;
        padding: 3px 8px; border-radius: 6px;
        background: rgba(255,255,255,0.08);
        color: var(--au-muted);
        border: none;
    }
