    }
}

// Processing-Core mit synchroner Frame-Verarbeitung
processor StereoWidenerCore
{
    input stream float32<2> in;
    output stream float32<2> out;

    input value float32 width;
    input value float32 lowCut;
    input value float32 monoCheck;
    input value float32 inputGain;

    // Filter-Zustand für Linkwitz-Riley Crossover (2-Pole Highpass)
    struct FilterState
    {
        float32 x1, x2, y1, y2;
    }

    FilterState hpL, hpR;

    // Allpass-Filter Zustand für Mono-zu-Stereo Wandlung
    float32 apStateR;

    void init()
    {
        hpL.x1 = 0.0f; hpL.x2 = 0.0f; hpL.y1 = 0.0f; hpL.y2 = 0.0f;
        hpR.x1 = 0.0f; hpR.x2 = 0.0f; hpR.y1 = 0.0f; hpR.y2 = 0.0f;
        apStateR = 0.0f;
    }

    void main()
    {
        loop
        {
            // 1. Gain-Stufe & Eingangskanäle synchron auslesen
            float32 inL = in[0] * inputGain;
            float32 inR = in[1] * inputGain;

            // 2. Synthetische Stereo-Weitung für reine Monosignale (Phasenstabil)
            if (abs(inL - inR) < 0.0001f)
            {
                float32 ap_g = 0.6f;
                float32 ap_in = inR;
                float32 ap_out = -ap_g * ap_in + apStateR;
                apStateR = ap_in + (ap_g * ap_out);
                inR = ap_out;
            }

            // 3. Koeffizienten für Frequenzweiche berechnen (12dB/Okt Linkwitz-Riley)
            float64 omega = 2.0 * double(processor.pi) * double(lowCut) / processor.frequency;
            float64 kappa = tan(omega / 2.0);
            float64 a0 = 1.0 / (1.0 + sqrt(2.0) * kappa + kappa * kappa);

            float32 b0 = float32(a0);
            float32 b1 = float32(-2.0 * a0);
            float32 b2 = float32(a0);
            float32 a1 = float32(2.0 * a0 * (kappa * kappa - 1.0));
            float32 a2 = float32(a0 * (1.0 - sqrt(2.0) * kappa + kappa * kappa));

            // 4. Filter pro Kanal anwenden (Hochpass-Anteil extrahieren)
            float32 hpOutL = (b0 * inL) + (b1 * hpL.x1) + (b2 * hpL.x2) - (a1 * hpL.y1) - (a2 * hpL.y2);
            hpL.x2 = hpL.x1; hpL.x1 = inL; hpL.y2 = hpL.y1; hpL.y1 = hpOutL;

            float32 hpOutR = (b0 * inR) + (b1 * hpR.x1) + (b2 * hpR.x2) - (a1 * hpR.y1) - (a2 * hpR.y2);
            hpR.x2 = hpR.x1; hpR.x1 = inR; hpR.y2 = hpR.y1; hpR.y1 = hpOutR;

            // Bassbereich isolieren (Low-Band bleibt unangetastet)
            float32 lowL = inL - hpOutL;
            float32 lowR = inR - hpOutR;

            // 5. Mid/Side Matrix auf dem High-Band anwenden
            float32 mid  = 0.5f * (hpOutL + hpOutR);
            float32 side = 0.5f * (hpOutL - hpOutR);

            // Weitungskoeffizient anwenden
            side = side * (width * 2.0f);

            // Re-Matrizierung nach L/R
            float32 wideHPL = mid + side;
            float32 wideHPR = mid - side;

            // 6. Signal-Rekombination
            float32 outL = lowL + wideHPL;
            float32 outR = lowR + wideHPR;

            // 7. Mono-Check Schalter einberechnen
            if (monoCheck > 0.5f)
            {
                float32 monoSum = 0.5f * (outL + outR);
                outL = monoSum;
                outR = monoSum;
            }

            // 8. Ausgabe als synchroner Stereo-Vektor
            out = float32<2>(outL, outR);

            advance();
        }
    }
}

