    // Filter-Koeffizienten für den Low Frequency Cut (Linkwitz-Riley 2-Pole Highpass)
    float hp_b0, hp_b1, hp_b2;
    float hp_a1, hp_a2;

    // Filter-Statusvariablen für Links und Rechts
    float xL_1, xL_2, yL_1, yL_2;
    float xR_1, xR_2, yR_1, yR_2;

    // Allpass-Filter für die phasenlineare Mono-zu-Stereo-Generierung
    float ap_stateL, ap_stateR;
    float ap_g;

public:
    void init(float sampleRate) {
        this->sampleRate = sampleRate;

        // Filter-Status zurücksetzen
        xL_1 = xL_2 = yL_1 = yL_2 = 0.0f;
        xR_1 = xR_2 = yR_1 = yR_2 = 0.0f;
        ap_stateL = ap_stateR = 0.0f;

        // Fester Koeffizient für die Allpass-Verzögerung (Mono-Umdichtung)
        // ca. 1.5ms Verzögerungs-Äquivalent für Frequenz-Phasensplitting
        float delaySamples = 0.0015f * sampleRate;
        ap_g = (delaySamples - 1.0f) / (delaySamples + 1.0f);
    }

    void updateFilter(float cutoffFreq) {
        // Berechne Linkwitz-Riley Tiefpass-/Hochpass-Koeffizienten basierend auf Cutoff
        float omega = PI * cutoffFreq / sampleRate;
        float theta = tan(omega);
        float kappa = theta / (1.0f + theta);

        // Standard Butterwoth 2. Ordnung Koeffizienten, kaskadiert für LR
        float resonance = 0.70710678f; 
        float c = 1.0f / tan(omega);

        float a0 = 1.0f / (1.0f + c * int(resonance * 2.0f) + c * c);
        hp_b0 = a0 * c * c;
        hp_b1 = -2.0f * hp_b0;
        hp_b2 = hp_b0;
        hp_a1 = 2.0f * a0 * (1.0f - c * c);
        hp_a2 = a0 * (1.0f - c * int(resonance * 2.0f) + c * c);
    }

    void process(float** inputs, float** outputs, int numSamples, float* parameters) {
        float width = parameters[PARAM_WIDTH];           // 0.0 - 1.0
        float lowCutFreq = parameters[PARAM_LOW_CUT];     // 20 - 500 Hz
        bool monoCheck = parameters[PARAM_MONO_CHECK] > 0.5f;

        // Aktualisiere Frequenzweiche
        updateFilter(lowCutFreq);

        for (int i = 0; i < numSamples; ++i) {
            float inL = inputs[0][i];
            float inR = inputs[1][i];

            // Falls das Signal komplett Mono ist (L == R), erzeugen wir ein künstliches, 
            // aber absolut mono-kompatibles Stereofeld mittels komplementärer Allpässe.
            if (std::abs(inL - inR) < 1e-5f) {
                // Allpass-Filterung auf dem rechten Kanal erzeugt Phasenversatz
                float ap_inR = inR;
                float ap_outR = -ap_g * ap_inR + ap_stateR;
                ap_stateR = ap_inR + ap_g * ap_outR;
                inR = ap_outR;
            }

            // 1. Highpass-Filterung für den Frequenz-Cut (Frequenzen unterhalb des Cuts isolieren)
            // Filter für linken Kanal
            float hpL = hp_b0 * inL + hp_b1 * xL_1 + hp_b2 * xL_2 - hp_a1 * yL_1 - hp_a2 * yL_2;
            xL_2 = xL_1; xL_1 = inL; yL_2 = yL_1; yL_1 = hpL;

            // Filter für rechten Kanal
            float hpR = hp_b0 * inR + hp_b1 * xR_1 + hp_b2 * xR_2 - hp_a1 * yR_1 - hp_a2 * yR_2;
            xR_2 = xR_1; xR_1 = inR; yR_2 = yR_1; yR_1 = hpR;

            // Tiefe Frequenzen (Low-Band), die unbearbeitet bleiben sollen
            float lowL = inL - hpL;
            float lowR = inR - hpR;

            // 2. Mid/Side Verarbeitung auf dem High-Band
            float mid = 0.5f * (hpL + hpR);
            float side = 0.5f * (hpL - hpR);

            // Skalierung des Side-Signals für die Verbreiterung (width = 0% bis 100%)
            // 0.0 = Komplett Mono (für das High-Band), 1.0 = Volle Breite
            float sideGain = width * 2.0f; 
            side *= sideGain;

            // Zurück nach L/R dekodieren (Nur für den Highpass-Anteil)
            float wideHPL = mid + side;
            float wideHPR = mid - side;

            // 3. Rekombination von unbearbeitetem Bassbereich und geweitetem Hochtonbereich
            float outL = lowL + wideHPL;
            float outR = lowR + wideHPR;

            // 4. Mono-Check Schalter (Summiert das finale Ausgangssignal zu Mono)
            if (monoCheck) {
                float monoSum = 0.5f * (outL + outR);
                outL = monoSum;
                outR = monoSum;
            }

            // Signal an die VST3-Ausgangs-Buffer übergeben
            outputs[0][i] = outL;
            outputs[1][i] = outR;
        }
    }
};

