            float64 kappa = std::tan(omega / 2.0);
            float64 a0 = 1.0 / (1.0 + std::sqrt(2.0) * kappa + kappa * kappa);

            float32 b0 = float32(a0);
            float32 b1 = float32(-2.0 * a0);
            float32 b2 = float32(a0);
            float32 a1 = float32(2.0 * a0 * (kappa * kappa - 1.0));
            float32 a2 = float32(a0 * (1.0 - std::sqrt(2.0) * kappa + kappa * kappa));

            // 4. Filter pro Kanal anwenden (Hochpass-Anteil isolieren)
            float32 hpOutL = (b0 * inL) + (b1 * hpL.x1) + (b2 * hpL.x2) - (a1 * hpL.y1) - (a2 * hpL.y2);
            hpL.x2 = hpL.x1; hpL.x1 = inL; hpL.y2 = hpL.y1; hpL.y1 = hpOutL;

            float32 hpOutR = (b0 * inR) + (b1 * hpR.x1) + (b2 * hpR.x2) - (a1 * hpR.y1) - (a2 * hpR.y2);
            hpR.x2 = hpR.x1; hpR.x1 = inR; hpR.y2 = hpR.y1; hpR.y1 = hpOutR;

            // Frequenzen unterhalb der Trennfrequenz abspalten
            float32 lowL = inL - hpOutL;
            float32 lowR = inR - hpOutR;

            // 5. Mid/Side Matrix auf das gefilterte High-Band anwenden
            float32 mid  = 0.5f * (hpOutL + hpOutR);
            float32 side = 0.5f * (hpOutL - hpOutR);

            // Weitungskoeffizient auf das Side-Signal rechnen
            side = side * (width * 2.0f);

            // Zurück nach L/R dekodieren
            float32 wideHPL = mid + side;
            float32 wideHPR = mid - side;

            // 6. Signal-Rekombination (Unbehandeltes Low-Band + Geweitetes High-Band)
            float32 outL = lowL + wideHPL;
            float32 outR = lowR + wideHPR;

            // 7. Mono-Check Schalter einberechnen
            if (monoCheck > 0.5f)
            {
                float32 monoSum = 0.5f * (outL + outR);
                outL = monoSum;
                outR = monoSum;
            }

            // 8. Ausgabe als synchroner Stereo-Vektor an den Ziel-Stream
            out = float32<2>(outL, outR);

            advance();
        }
    }
}

