    {
        hpL.x1 = 0.0f; hpL.x2 = 0.0f; hpL.y1 = 0.0f; hpL.y2 = 0.0f;
        hpR.x1 = 0.0f; hpR.x2 = 0.0f; hpR.y1 = 0.0f; hpR.y2 = 0.0f;
        apStateR = 0.0f;
    }

    void main()
    {
        loop
        {
            // 1. Gain-Stufe & Eingangssignale über Indizes aus dem Stereo-Vektor extrahieren
            float32 inL = in[0] * inputGain;
