            // 5. Mid/Side Matrix auf das gefilterte High-Band anwenden
            float32 mid  = 0.5f * (hpOutL + hpOutR);
            float32 side = 0.5f * (hpOutL - hpOutR);

            // Weitungskoeffizient auf das Side-Signal rechnen
            side = side * (width * 2.0f);

            // Zurück nach L/R dekodieren
            float32 wideHPL = mid + side;
            float32 wideHPR = mid - side;

            // 6. Signal-Rekombination (Unbehandeltes Low-Band + Geweitetes High-Band)
            float32 outL = lowL + wideHPL;
            float32 outR = lowR + wideHPR;

            // 7. Mono-Check Schalter einberechnen
            if (monoCheck > 0.5f)
            {
                float32 monoSum = 0.5f * (outL + outR);
                outL = monoSum;
                outR = monoSum;
